void MyProcControl_Lite::ConfigTool::doLayout() {
	if (!listView.created()) return;

	RECT rc = client_rect();
	int W = rc.right - rc.left;
	int H = rc.bottom - rc.top;
	int top = MARGIN;
	
	// elevation banner (conditional)
	if (!isAdmin) {
		elevateText.show();
		elevateBtn.show();
		elevateText.resize(MARGIN, top,
			W - MARGIN * 2 - BTN_WIDTH - GAP, BANNER_HEIGHT);
		elevateBtn.resize(W - MARGIN - BTN_WIDTH, top,
			BTN_WIDTH, BANNER_HEIGHT);
		top += BANNER_HEIGHT + GAP;
	} else {
		elevateText.hide();
		elevateBtn.hide();
	}

	// target row
	targetText.resize(MARGIN, top,
		W - MARGIN * 2 - CHANGE_BTN_WIDTH - GAP, ROW_HEIGHT);
	changeBtn.resize(W - MARGIN - CHANGE_BTN_WIDTH, top,
		CHANGE_BTN_WIDTH, ROW_HEIGHT);
	top += ROW_HEIGHT + GAP;

	// list view (fills remaining space above button row)
	int bottomY = H - MARGIN - BUTTON_HEIGHT;
	int listH = bottomY - GAP - top;
	if (listH < 50) listH = 50;
	listView.resize(MARGIN, top, W - MARGIN * 2, listH);
	listView.autoSizeLastColumn(COL_NAME_WIDTH, COL_VALUE_WIDTH);

	// bottom buttons — right aligned: Uninstall | Configure Now | Cancel
	int cancelX    = W - MARGIN - BTN_WIDTH;
	int configureX = cancelX - GAP - CONFIG_BTN_WIDTH;
	int uninstallX = configureX - GAP - BTN_WIDTH;
	cancelBtn.resize(cancelX, bottomY, BTN_WIDTH, BUTTON_HEIGHT);
	configureBtn.resize(configureX, bottomY, CONFIG_BTN_WIDTH, BUTTON_HEIGHT);
	uninstallBtn.resize(uninstallX, bottomY, BTN_WIDTH, BUTTON_HEIGHT);
}

