bool MyProcControl_Lite::ConfigTool::checkIsAdmin() {
	return IsUserAnAdmin() != FALSE;
}

void MyProcControl_Lite::ConfigTool::checkServiceStatus() {
	serviceInstalled = false;
	// read-only SCM access — works for standard users.
	// Use default-ctor + assign because w32BaseHandle's value ctor throws on NULL.
	w32ServiceHandle scm;
	scm = OpenSCManagerW(nullptr, nullptr, SC_MANAGER_CONNECT);
	if (!scm.is_valid()) return;
	w32ServiceHandle hService;
	hService = OpenServiceW(scm, svc.c_str(), SERVICE_QUERY_STATUS);
	serviceInstalled = hService.is_valid();
}

void MyProcControl_Lite::ConfigTool::loadConfigFromRegistry() {
	itemValues.assign(ITEM_COUNT, std::any{});
	for (size_t i = 0; i < ITEM_COUNT; ++i)
		itemValues[i] = itemDefs[i].defaultValue;

	if (!serviceInstalled) return;
	try {
		RegistryKey params(HKEY_LOCAL_MACHINE,
			L"SYSTEM\\CurrentControlSet\\Services\\" + svc + L"\\Parameters", KEY_READ);
		for (size_t i = 0; i < ITEM_COUNT; ++i)
			itemValues[i] = read_any_from_registry(params, itemDefs[i].name, itemDefs[i].defaultValue);
	} catch (...) {
		// key absent or unreadable — defaults already applied
	}
}

void MyProcControl_Lite::ConfigTool::populateListView() {
	listView.deleteAllItems();
	for (size_t i = 0; i < ITEM_COUNT; ++i) {
		int idx = listView.addItem(itemDefs[i].name);
		listView.setItemText(idx, 1, any_to_display(itemValues[i]));
		listView.setItemText(idx, 2, itemDefs[i].description);
	}
}

void MyProcControl_Lite::ConfigTool::updateButtonStates() {
	if (!serviceInstalled) {
		uninstallBtn.disable();
		configureBtn.text(L"Install && Configure");
	} else {
		uninstallBtn.enable();
		configureBtn.text(L"Configure Now");
	}
	if (!isAdmin) {
		uninstallBtn.disable();
		configureBtn.disable();
	}
	targetText.color(serviceInstalled ? RgbColor("#080") : RgbColor("#f00"));
}

